const prices = [5, 12, 8];

const doubled = prices.map(price => price * 2);
const big = prices.filter(price => price > 6);
const label = (name, count) => `${name}: ${count}`;
const zero = () => 0;

console.log(doubled.join(","));
console.log(label("big", big.length));
console.log(zero() + doubled[0]);
